import { useEffect, useState } from 'react'
import { AlertTriangle, BarChart3 } from 'lucide-react'
import { reportApi, type Vendor } from '../../api'
import { Card, CardContent, CardHeader } from '../../components/ui/card'

export function ReportsPage({ vendor, storeId }: { vendor?: Vendor; storeId?: number }) { const [sales, setSales] = useState<{ saleCount: number; subtotal: number; discount: number; vat: number; total: number } | null>(null); const [lowStock, setLowStock] = useState<{ productName: string; quantity: number; reorderLevel: number }[]>([]); const [expiration, setExpiration] = useState<{ productName: string; quantity: number; expirationDate: string }[]>([]); useEffect(() => { if (!vendor || !storeId) return; reportApi.sales(vendor.id, storeId).then(setSales).catch(() => setSales(null)); reportApi.lowStock(vendor.id, storeId).then(setLowStock).catch(() => setLowStock([])); reportApi.expiration(vendor.id, storeId).then(setExpiration).catch(() => setExpiration([])) }, [vendor, storeId]); return <><PageIntro title="Reports" text="Review sales totals, stock warnings, and expiration risk for the selected store." /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Sales" value={sales ? `PHP ${sales.total.toLocaleString()}` : '—'} detail={sales ? `${sales.saleCount} sales` : 'Select a store'} /><Metric label="Subtotal" value={sales ? `PHP ${sales.subtotal.toLocaleString()}` : '—'} detail="Before discounts and VAT" /><Metric label="Discounts" value={sales ? `PHP ${sales.discount.toLocaleString()}` : '—'} detail="Recorded discounts" /><Metric label="VAT" value={sales ? `PHP ${sales.vat.toLocaleString()}` : '—'} detail="VAT collected" /></div><div className="mt-6 grid gap-5 lg:grid-cols-2"><ReportList title="Low stock" icon={<AlertTriangle className="text-amber-600" size={18} />} items={lowStock.map(item => `${item.productName} · ${item.quantity} left (reorder ${item.reorderLevel})`)} /><ReportList title="Near expiration" icon={<AlertTriangle className="text-rose-600" size={18} />} items={expiration.map(item => `${item.productName} · ${item.quantity} units · ${item.expirationDate}`)} /></div></> }
function Metric({ label, value, detail }: { label: string; value: string; detail: string }) { return <Card><CardContent className="p-4"><p className="text-xs font-semibold text-slate-500">{label}</p><strong className="mt-2 block text-2xl font-black">{value}</strong><small className="mt-2 block text-xs text-slate-400">{detail}</small></CardContent></Card> }
function ReportList({ title, icon, items }: { title: string; icon: React.ReactNode; items: string[] }) { return <Card><CardHeader><div className="flex items-center gap-2"><BarChart3 size={17} className="text-indigo-600" /><h2 className="font-bold">{title}</h2>{icon}</div></CardHeader><CardContent>{items.length ? <div className="space-y-2">{items.map(item => <p key={item} className="rounded-lg bg-slate-50 p-3 text-xs font-semibold text-slate-600">{item}</p>)}</div> : <p className="text-sm text-slate-500">No alerts for this store.</p>}</CardContent></Card> }
function PageIntro({ title, text }: { title: string; text: string }) { return <div className="mb-6"><p className="text-[11px] font-bold uppercase tracking-[.17em] text-indigo-600">Business intelligence</p><h1 className="mt-1.5 text-3xl font-black tracking-[-.055em]">{title}</h1><p className="mt-2 text-[13px] text-slate-500">{text}</p></div> }
